    const total=3+Math.floor(rand()*3),r=rand();
    const hab=i===0||i===neighbor?1:r<MAP_CONFIG.HAB_CHANCES[0]?0:r<MAP_CONFIG.HAB_CHANCES[0]+MAP_CONFIG.HAB_CHANCES[1]?1:2;
    let arr=[];
