      const slots=total-arr.length,ratios=[['mineral',MAP_CONFIG.GENERAL_CHANCES[0]],['gas',MAP_CONFIG.GENERAL_CHANCES[1]],['barren',MAP_CONFIG.GENERAL_CHANCES[2]]];
